window.AUTH=window.AUTH||{};window.AUTH["05-1342"]={"d":"05-1342","id":"2006/05-1342","n":"Watters v. Wachovia Bank, N.A.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondents","date":"","url":"https://www.justice.gov/osg/media/212896/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/watters-v-wachovia-bank-na-amicus-merits","n":58}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep550/usrep550001/usrep550001.pdf","tr":true,"items":[{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"op":2,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Barnett Bank of Marion County, N.A. v. Nelson","cite":"517 U.S. 25","y":1995,"id":"1995/94-1837","sc":1,"op":14,"ar":4,"sum":"The Federal Statute pre-empts the State Statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Capital Cities Cable, Inc. v. Crisp","cite":"467 U.S. 691","y":1984,"id":"1983/82-1795","sc":1,"sum":"The Court held unanimously that Oklahoma's ban on local cable transmissions of out-of-state alcoholic beverage commercials violated both the Supremacy and Commerce Clauses. While Oklahoma can regulate local cable aspects, such as franchise formation and construction, it cannot tamper with the flow of information from other states.","sumSrc":"Oyez","by":{"0":"10, 13"}},{"t":"case","label":"Chevron U.S.A., Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":5,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"6, 12, 13, 19, 22"}},{"t":"case","label":"Citizens Bank v. Alafabco, Inc.","cite":"539 U.S. 52","y":2003,"id":"2002/02-1295","sc":1,"op":1,"sum":"The Court held that the parties’ debt-restructuring agreement affected interstate commerce, and therefore their arbitration clause was enforceable under the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"City of New York v. FCC","cite":"486 U.S. 57","y":1988,"id":"1987/87-339","sc":1,"op":1,"sum":"The FCC did not exceed its statutory authority by forbidding local authorities to impose technical cable signal quality standards more stringent than those set forth in the Commission's regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Clarke v. Securities Indus. Ass’n","cite":"479 U.S. 388","y":1987,"id":"1986/85-971","sc":1,"op":1,"sum":"Petitioner Security Pacific National Bank (Security Pacific) applied to the Comptroller of the Currency for permission to establish an affiliate named Discount Brokerage, and to offer discount brokerage services not only at its branch offices but also at other locations inside and outside of its home State. A pertinent branching provision of the National Bank Act, 12 U. S. C. § 81, originally enacted in 1927 as part …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Conference of State Bank Supervisors v. Conover","cite":"710 F.2d 878","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/710/878/","op":1,"by":{"0":"15, 23"}},{"t":"case","label":"Easton v. Iowa","cite":"188 U.S. 220","y":1903,"id":"scdb/1902-051","sc":1,"op":1,"sum":"Congress having power to create a system of national banks, is the judge as to the extent of the powers which should he conferred upon such banks, and has the sole power to regulate and control the exercise of their operations. Congress having dealt directly with the insolvency of national banks by giving control to the Secretary of the Treasury and the Comptroller of the Currency, who are authorized to suspendthe …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Farmers & Mechanics Nat’l Bank v. Dearing","cite":"91 U.S. 29","y":1875,"id":"scdb/1875-007","sc":1,"op":1,"by":{"0":"9"}},{"t":"case","label":"Fidelity Fed. Sav. & Loan Ass’n v. De la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"op":2,"sum":"Holding that a regulation authorizing federal savings-and-loan associations to include due-on-sale clauses in mortgage contracts conﬂicted with a state-court doctrine that such clauses were un­ enforceable.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"case","label":"First Nat’l Bank v. California","cite":"262 U.S. 366","y":1923,"id":"scdb/1922-201","sc":1,"op":9,"ar":3,"sum":"A state law providing for the escheat to the State of bank deposits after they have remained intact and unclaimed for more than twenty years, when no notice of his residence has been filed with the bank by the depositor or any claimant, is void as applied to deposits in National Banks. Calif. Code Civ. Proc. § 1273; U. S. Rev. Stats., § 5136. P. 369. 186 Cal. 746, reversed. ERROR to a judgment of the Supreme Court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Franklin Nat’l Bank v. New York","cite":"347 U.S. 373","y":1954,"id":"scdb/1953-060","sc":1,"op":4,"ar":2,"sum":"Insofar as it forbids national banks to use the word \"saving\" or \"savings\" in their business or advertising, the New York statute here involved is invalid, because it conflicts with federal laws expressly authorizing national banks to receive savings deposits and to exercise incidental powers.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"op":2,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"24, 28, 30"}},{"t":"case","label":"Hillsborough County v. Automated Med. Labs., Inc.","cite":"471 U.S. 707","y":1985,"id":"1984/83-1925","sc":1,"op":1,"sum":"Appellant county's ordinances and implementing regulations are not pre-empted by the federal regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Louisiana Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 24, 25"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"op":2,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"0":"24, 25, 28"}},{"t":"case","label":"National City Bank v. Turnbaugh","cite":"463 F.3d 325","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/463/325/","op":2,"sum":"Holding that state law conﬂicted with the OCC regu­ lations, not with the NBA.","sumSrc":"opinion","by":{"0":"9, 13"}},{"t":"case","label":"Nationsbank of N.C., N.A. v. Variable Annuity Life Ins. Co.","cite":"513 U.S. 251","y":1995,"id":"1994/93-1612","sc":1,"op":3,"sum":"Upholding the OCC’s interpretation of the “incidental powers” provision to permit national banks to serve as agents in annuity sales.","sumSrc":"opinion","by":{"0":"1, 2, 13, 14, 19"}},{"t":"case","label":"New York v. FERC","cite":"535 U.S. 1","y":2002,"id":"2001/00-568","sc":1,"sum":"The Court held that FERC properly construed its statutory authority.","sumSrc":"Oyez","by":{"0":"23, 24"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"op":2,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"29, 30"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Smiley v. Citibank (S.D.), N.A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"op":5,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"0":"13, 24"}},{"t":"case","label":"Tiffany v. National Bank","cite":"85 U.S. 409","y":1874,"id":"scdb/1873-091","sc":1,"op":1,"sum":"Tiffany, trustee of Darby, a bankrupt, brought an action of debt iti the court below against the National.Bank of Missouri, a corporation organized under the National Banking Act of June 3d, 1864, to recover under the provisions of the 'thirtieth section of the act twice the amount of interest paid by the said Darby, on certain loans made by the bank to him before he was adjudged a bankrupt. The ground of the action …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"United States v. Locke","cite":"529 U.S. 89","y":2000,"id":"1999/98-1701","sc":1,"op":1,"sum":"The Court held that Washington's regulations regarding general navigation watch procedures, crew English-language skills and training, and maritime casualty reporting are pre-empted by the comprehensive federal regulatory scheme governing oil tankers. \"The State of Washington has enacted legislation in an area where the federal interest has been manifest since the beginning of our Republic and is now well established,\" wrote Justice Kennedy for the Court.","sumSrc":"Oyez","by":{"0":"10, 22"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"13, 14"}},{"t":"case","label":"United States v. Shimer","cite":"367 U.S. 374","y":1961,"id":"1960/392","sc":1,"sum":"The judgment is reversed, since the courts below erred in applying a state statute which was in conflict with a valid Regulation of the Veterans' Administration issued pursuant to the Act and agreed to by the veteran when the loan was made.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Wachovia Bank N.A. v. Burke","cite":"414 F.3d 305","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/414/305/","op":2,"by":{"0":"9, 13"}},{"t":"case","label":"Wells Fargo Bank N.A. v. Boutris","cite":"419 F.3d 949","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/419/949/","op":4,"by":{"0":"10, 13, 20"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"0":"6, 7, 28, 30"}},{"t":"usc","label":"12 U.S.C. § 3801","url":"https://www.law.cornell.edu/uscode/text/12/3801","by":{"0":"18"}},{"t":"law","label":"Gramm-Leach-Bliley Act, Pub. L. No. 106-102","url":"https://www.govinfo.gov/link/plaw/106/public/102","by":{"0":"20"}},{"t":"usc","label":"12 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/12/1","stext":{"head":"§1. Office of the Comptroller of the Currency","paras":[[0,"(a) Office of the Comptroller of the Currency established"],[0,"There is established in the Department of the Treasury a bureau to be known as the \"Office of the Comptroller of the Currency\" which is charged with assuring the safety and soundness of, and compliance with laws and regulations, fair access to financial services, and fair treatment of customers by, the institutions and other persons subject to its jurisdiction."],[0,"(b) Comptroller of the Currency"],[0,"(1) In general"],[1,"The chief officer of the Office of the Comptroller of the Currency shall be known as the Comptroller of the Currency. The Comptroller of the Currency shall perform the duties of the Comptroller of the Currency under the general direction of the Secretary of the Treasury. The Secretary of the Treasury may not delay or prevent the issuance of any rule or the promulgation of any regulation by the Comptroller of the Currency, and may not intervene in any matter or proceeding before the Comptroller of the Currency (including agency enforcement actions), unless otherwise specifically provided by law."],[0,"(2) Additional authority"],[1,"The Comptroller of the Currency shall have the same authority with respect to functions transferred to the Comptroller of the Currency under the Enhancing Financial Institution Safety and Soundness Act of 2010 as was vested in the Director of the Office of Thrift Supervision on the transfer date, as defined in section 311 of that Act [12 U.S.C. 5411]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. Office of the Comptroller of the Currency","tname":"Banks and Banking","by":{"0":"passim, 13"}},{"t":"usc","label":"12 U.S.C. § 24","url":"https://www.law.cornell.edu/uscode/text/12/24","stext":{"head":"§24. Corporate powers of associations","paras":[[0,"Upon duly making and filing articles of association and an organization certificate a national banking association shall become, as from the date of the execution of its organization certificate, a body corporate, and as such, and in the name designated in the organization certificate, it shall have power—"],[0,"First. To adopt and use a corporate seal."],[0,"Second. To have succession from February 25, 1927, or from the date of its organization if organized after February 25, 1927, until such time as it be dissolved by the act of its shareholders owning two-thirds of its stock, or until its franchise becomes forfeited by reason of violation of law, or until terminated by either a general or a special Act of Congress or until its affairs be placed in the hands of a receiver and finally wound up by him."],[0,"Third. To make contracts."],[0,"Fourth. To sue and be sued, complain and defend, in any court of law and equity, as fully as natural persons."],[0,"Fifth. To elect or appoint directors, and by its board of directors to appoint a president, vice president, cashier, and other officers, define their duties, require bonds of them and fix the penalty thereof, dismiss such officers or any of them at pleasure, and appoint others to fill their places."],[0,"Sixth. To prescribe, by its board of directors, bylaws not inconsistent with law, regulating the manner in which its stock shall be transferred, its directors elected or appointed, its officers appointed, its property transferred, its general business conducted, and the privileges granted to it by law exercised and enjoyed."],[0,"Seventh. To exercise by its board of directors or duly authorized officers or agents, subject to law, all such incidental powers as shall be necessary to carry on the business of banking; by discounting and negotiating promissory notes, drafts, bills of exchange, and other evidences of debt; by receiving deposits; by buying and selling exchange, coin, and bullion; by loaning money on personal security; and by obtaining, issuing, and circulating notes according to the provisions of title 62 of the Revised Statutes. The business of dealing in securities and stock by the association shall be limited to purchasing and selling such securities and stock without recourse, solely upon the order, and for the account of, customers, and in no case for its own account, and the association shall not underwrite any issue of securities or stock; Provided, That the association may purchase for its own account investment securities under such limitations and restrictions as the Comptroller of the Currency may by regulation prescribe. In no event shall the total amount of the investment securities of any one obligor or maker, held by the association for its own account, exceed at any time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund, except that this limitation shall not require any association to dispose of any securities lawfully held by it on August 23, 1935. As used in this section the term \"investment securities\" shall mean marketable obligations, evidencing indebtedness of any person, copartnership, association, or corporation in the form of bonds, notes and/or debentures commonly known as investment securities under such further definition of the term \"investment securities\" as may by regulation be prescribed by the Comptroller of the Currency. Except as hereinafter provided or otherwise permitted by law, nothing herein contained shall authorize the purchase by the association for its own account of any shares of stock of any corporation. The limitations and restrictions herein contained as to dealing in, underwriting and purchasing for its own account, investment securities shall not apply to obligations of the United States, or general obligations of any State or of any political subdivision thereof, or obligations of the Washington Metropolitan Area Transit Authority which are guaranteed by the Secretary of Transportation under section 9 of the National Capital Transportation Act of 1969, or obligations issued under authority of the Federal Farm Loan Act, as amended, or issued by the thirteen banks for cooperatives or any of them or the Federal Home Loan Banks, or obligations which are insured by the Secretary of Housing and Urban Development under title XI of the National Housing Act [12 U.S.C. 1749aaa et seq.] or obligations which are insured by the Secretary of Housing and Urban Development (hereinafter in this sentence referred to as the \"Secretary\") pursuant to section 207 of the National Housing Act [12 U.S.C. 1713], if the debentures to be issued in payment of such insured obligations are guaranteed as to principal and interest by the United States, or obligations, participations, or other instruments of or issued by the Federal National Mortgage Association, or the Government National Mortgage Association, or mortgages, obligations or other securities which are or ever have been sold by the Federal Home Loan Mortgage Corporation pursuant to section 305 or section 306 of the Federal Home Loan Mortgage Corporation Act [12 U.S.C. 1454 or 1455], or obligations of the Federal Financing Bank or obligations of the Environmental Financing Authority, or obligations or other instruments or securities of the Student Loan Marketing Association, or such obligations of any local public agency (as defined in section 110(h) of the Housing Act of 1949 [42 U.S.C. 1460(h)]) as are secured by an agreement between the local public agency and the Secretary in which the local public agency agrees to borrow from said Secretary, and said Secretary agrees to lend to said local public agency, monies in an aggregate amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay, when due, the interest on and all installments (including the final installment) of the principal of such obligations, which monies under the terms of said agreement are required to be used for such payments, or such obligations of a public housing agency (as defined in the United States Housing Act of 1937, as amended [42 U.S.C. 1437 et seq.]) as are secured (1) by an agreement between the public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of such obligations, monies in an amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay the principal of such obligations with interest to maturity thereon, which monies under the terms of said agreement are required to be used for the purpose of paying the principal of and the interest on such obligations at their maturity, (2) by a pledge of annual contributions under an annual contributions contract between such public housing agency and the Secretary if such contract shall contain the covenant by the Secretary which is authorized by subsection (g) of section 6 of the United States Housing Act of 1937, as amended [42 U.S.C. 1437d(g)], and if the maximum sum and the maximum period specified in such contract pursuant to said subsection 6(g) [42 U.S.C. 1437d(g)] shall not be less than the annual amount and the period for payment which are requisite to provide for the payment when due of all installments of principal and interest on such obligations, or (3) by a pledge of both annual contributions under an annual contributions contract containing the covenant by the Secretary which is authorized by section 6(g) of the United States Housing Act of 1937 [42 U.S.C. 1437d(g)], and a loan under an agreement between the local public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of the obligations involved, moneys in an amount which (together with any other moneys irrevocably committed under the annual contributions contract to the payment of principal and interest on such obligations) will suffice to provide for the payment when due of all installments of principal and interest on such obligations, which moneys under the terms of the agreement are required to be used for the purpose of paying the principal and interest on such obligations at their maturity: Provided, That in carrying on the business commonly known as the safe-deposit business the association shall not invest in the capital stock of a corporation organized under the law of any State to conduct a safe-deposit business in an amount in excess of 15 per centum of the capital stock of the association actually paid in and unimpaired and 15 per centum of its unimpaired surplus. The limitations and restrictions herein contained as to dealing in and underwriting investment securities shall not apply to obligations issued by the International Bank for Reconstruction and Development, the European Bank for Reconstruction and Development, the Inter-American Development Bank 1 Bank for Economic Cooperation and Development in the Middle East and North Africa,,2 the North American Development Bank, the Asian Development Bank, the African Development Bank, the Inter-American Investment Corporation, or the International Finance Corporation,,2 or obligations issued by any State or political subdivision or any agency of a State or political subdivision for housing, university, or dormitory purposes, which are at the time eligible for purchase by a national bank for its own account, nor to bonds, notes and other obligations issued by the Tennessee Valley Authority or by the United States Postal Service: Provided, That no association shall hold obligations issued by any of said organizations as a result of underwriting, dealing, or purchasing for its own account (and for this purpose obligations as to which it is under commitment shall be deemed to be held by it) in a total amount exceeding at any one time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation authorized to be created pursuant to title IX of the Housing and Urban Development Act of 1968 [42 U.S.C. 3931 et seq.], and may make investments in a partnership, limited partnership, or joint venture formed pursuant to section 907(a) or 907(c) of that Act [42 U.S.C. 3937(a) or 3937(c)]. Notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock issued by any State housing corporation incorporated in the State in which the association is located and may make investments in loans and commitments for loans to any such corporation: Provided, That in no event shall the total amount of such stock held for its own account and such investments in loans and commitments made by the association exceed at any time 5 per centum of its capital stock actually paid in and unimpaired plus 5 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation organized solely for the purpose of making loans to farmers and ranchers for agricultural purposes, including the breeding, raising, fattening, or marketing of livestock. However, unless the association owns at least 80 per centum of the stock of such agricultural credit corporation the amount invested by the association at any one time in the stock of such corporation shall not exceed 20 per centum of the unimpaired capital and surplus of the association: Provided further, That notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock of a bank insured by the Federal Deposit Insurance Corporation or a holding company which owns or controls such an insured bank if the stock of such bank or company is owned exclusively (except to the extent directors' qualifying shares are required by law) by depository institutions or depository institution holding companies (as defined in section 1813 of this title) and such bank or company and all subsidiaries thereof are engaged exclusively in providing services to or for other depository institutions, their holding companies, and the officers, directors, and employees of such institutions and companies, and in providing correspondent banking services at the request of other depository institutions or their holding companies (also referred to as a \"banker's bank\"), but in no event shall the total amount of such stock held by the association in any bank or holding company exceed at any time 10 per centum of the association's capital stock and paid in and unimpaired surplus and in no event shall the purchase of such stock result in an association's acquiring more than 5 per centum of any class of voting securities of such bank or company. The limitations and restrictions contained in this paragraph as to an association purchasing for its own account investment securities shall not apply to securities that (A) are offered and sold pursuant to section 4(5) of the Securities Act of 1933 (15 U.S.C. 77d(5)); 3 (B) are small business related securities (as defined in section 3(a)(53) of the Securities Exchange Act of 1934 [15 U.S.C. 78c(a)(53)]); or (C) are mortgage related securities (as that term is defined in section 3(a)(41) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(41)).4 The exception provided for the securities described in subparagraphs (A), (B), and (C) shall be subject to such regulations as the Comptroller of the Currency may prescribe, including regulations prescribing minimum size of the issue (at the time of initial distribution) or minimum aggregate sales prices, or both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/24?type=usc&year=mostrecent&link-type=html"},"op":16,"ar":1,"head":"§24. Corporate powers of associations","tname":"Banks and Banking","by":{"0":"2, 2, 8, 14, 17, 19"}},{"t":"usc","label":"12 U.S.C. § 24a","url":"https://www.law.cornell.edu/uscode/text/12/24a","subs":["(a)(2)(A)(ii)","(g)(3)(A)"],"stext":{"head":"§24a. Financial subsidiaries of national banks","paras":[[0,"(a) Authorization to conduct in subsidiaries certain activities that are financial in nature"],[0,"(1) In general"],[1,"Subject to paragraph (2), a national bank may control a financial subsidiary, or hold an interest in a financial subsidiary."],[0,"(2) Conditions and requirements"],[1,"A national bank may control a financial subsidiary, or hold an interest in a financial subsidiary, only if—"],[2,"(A) the financial subsidiary engages only in—"],[3,"(i) activities that are financial in nature or incidental to a financial activity pursuant to subsection (b); and"],[3,"(ii) activities that are permitted for national banks to engage in directly (subject to the same terms and conditions that govern the conduct of the activities by a national bank);"],[2,"(B) the activities engaged in by the financial subsidiary as a principal do not include—"],[3,"(i) insuring, guaranteeing, or indemnifying against loss, harm, damage, illness, disability, or death (except to the extent permitted under section 302 or 303(c) of the Gramm-Leach-Bliley Act [15 U.S.C. 6712 or 6713(c)]) or providing or issuing annuities the income of which is subject to tax treatment under section 72 of title 26;"],[3,"(ii) real estate development or real estate investment activities, unless otherwise expressly authorized by law; or"],[3,"(iii) any activity permitted in subparagraph (H) or (I) of section 1843(k)(4) of this title, except activities described in section 1843(k)(4)(H) of this title that may be permitted in accordance with section 122 of the Gramm-Leach-Bliley Act;"],[2,"(C) the national bank and each depository institution affiliate of the national bank are well capitalized and well managed;"],[2,"(D) the aggregate consolidated total assets of all financial subsidiaries of the national bank do not exceed the lesser of—"],[3,"(i) 45 percent of the consolidated total assets of the parent bank; or"],[3,"(ii) $50,000,000,000;"],[2,"(E) except as provided in paragraph (4), the national bank meets standards of credit-worthiness established by the Comptroller of the Currency or other requirement set forth in paragraph (3); and"],[2,"(F) the national bank has received the approval of the Comptroller of the Currency for the financial subsidiary to engage in such activities, which approval shall be based solely upon the factors set forth in this section."],[0,"(3) Requirement"],[0,"(A) In general"],[2,"A national bank meets the requirements of this paragraph if the bank is one of the 100 largest insured banks and has not fewer than 1 issue of outstanding debt that meets standards of credit-worthiness or other criteria as the Secretary of the Treasury and the Board of Governors of the Federal Reserve System may jointly establish."],[0,"(B) Consolidated total assets"],[2,"For purposes of this paragraph, the size of an insured bank shall be determined on the basis of the consolidated total assets of the bank as of the end of each calendar year."],[0,"(4) Financial agency subsidiary"],[1,"The requirement in paragraph (2)(E) shall not apply with respect to the ownership or control of a financial subsidiary that engages in activities described in subsection (b)(1) solely as agent and not directly or indirectly as principal."],[0,"(5) Regulations required"],[1,"Before the end of the 270-day period beginning on November 12, 1999, the Comptroller of the Currency shall, by regulation, prescribe procedures to implement this section."],[0,"(6) Indexed asset limit"],[1,"The dollar amount contained in paragraph (2)(D) shall be adjusted according to an indexing mechanism jointly established by regulation by the Secretary of the Treasury and the Board of Governors of the Federal Reserve System."],[0,"(7) Coordination with section 1843(l)(2) of this title"],[1,"Section 1843(l)(2) of this title applies to a national bank that controls a financial subsidiary in the manner provided in that section."],[0,"(b) Activities that are financial in nature"],[0,"(1) Financial activities"],[0,"(A) In general"],[2,"An activity shall be financial in nature or incidental to such financial activity only if—"],[3,"(i) such activity has been defined to be financial in nature or incidental to a financial activity for bank holding companies pursuant to section 1843(k)(4) of this title; or"],[3,"(ii) the Secretary of the Treasury determines the activity is financial in nature or incidental to a financial activity in accordance with subparagraph (B)."],[0,"(B) Coordination between the Board and the Secretary of the Treasury"],[0,"(i) Proposals raised before the Secretary of the Treasury"],[0,"(I) Consultation"],[4,"The Secretary of the Treasury shall notify the Board of, and consult with the Board concerning, any request, proposal, or application under this section for a determination of whether an activity is financial in nature or incidental to a financial activity."],[0,"(II) Board view"],[4,"The Secretary of the Treasury shall not determine that any activity is financial in nature or incidental to a financial activity under this section if the Board notifies the Secretary in writing, not later than 30 days after the date of receipt of the notice described in subclause (I) (or such longer period as the Secretary determines to be appropriate under the circumstances) that the Board believes that the activity is not financial in nature or incidental to a financial activity or is not otherwise permissible under this section."],[0,"(ii) Proposals raised by the Board"],[0,"(I) Board recommendation"],[4,"The Board may, at any time, recommend in writing that the Secretary of the Treasury find an activity to be financial in nature or incidental to a financial activity for purposes of this section."],[0,"(II) Time period for secretarial action"],[4,"Not later than 30 days after the date of receipt of a written recommendation from the Board under subclause (I) (or such longer period as the Secretary of the Treasury and the Board determine to be appropriate under the circumstances), the Secretary shall determine whether to initiate a public rulemaking proposing that the subject recommended activity be found to be financial in nature or incidental to a financial activity under this section, and shall notify the Board in writing of the determination of the Secretary and, in the event that the Secretary determines not to seek public comment on the proposal, the reasons for that determination."],[0,"(2) Factors to be considered"],[1,"In determining whether an activity is financial in nature or incidental to a financial activity, the Secretary shall take into account—"],[2,"(A) the purposes of this Act 1 and the Gramm-Leach-Bliley Act;"],[2,"(B) changes or reasonably expected changes in the marketplace in which banks compete;"],[2,"(C) changes or reasonably expected changes in the technology for delivering financial services; and"],[2,"(D) whether such activity is necessary or appropriate to allow a bank and the subsidiaries of a bank to—"],[3,"(i) compete effectively with any company seeking to provide financial services in the United States;"],[3,"(ii) efficiently deliver information and services that are financial in nature through the use of technological means, including any application necessary to protect the security or efficacy of systems for the transmission of data or financial transactions; and"],[3,"(iii) offer customers any available or emerging technological means for using financial services or for the document imaging of data."],[0,"(3) Authorization of new financial activities"],[1,"The Secretary of the Treasury shall, by regulation or order and in accordance with paragraph (1)(B), define, consistent with the purposes of this Act 1 and the Gramm-Leach-Bliley Act, the following activities as, and the extent to which such activities are, financial in nature or incidental to a financial activity:"],[2,"(A) Lending, exchanging, transferring, investing for others, or safeguarding financial assets other than money or securities."],[2,"(B) Providing any device or other instrumentality for transferring money or other financial assets."],[2,"(C) Arranging, effecting, or facilitating financial transactions for the account of third parties."],[0,"(c) Capital deduction"],[0,"(1) Capital deduction required"],[1,"In determining compliance with applicable capital standards—"],[2,"(A) the aggregate amount of the outstanding equity investment, including retained earnings, of a national bank in all financial subsidiaries shall be deducted from the assets and tangible equity of the national bank; and"],[2,"(B) the assets and liabilities of the financial subsidiaries shall not be consolidated with those of the national bank."],[0,"(2) Financial statement disclosure of capital deduction"],[1,"Any published financial statement of a national bank that controls a financial subsidiary shall, in addition to providing information prepared in accordance with generally accepted accounting principles, separately present financial information for the bank in the manner provided in paragraph (1)."],[0,"(d) Safeguards for the bank"],[0,"A national bank that establishes or maintains a financial subsidiary shall assure that—"],[1,"(1) the procedures of the national bank for identifying and managing financial and operational risks within the national bank and the financial subsidiary adequately protect the national bank from such risks;"],[1,"(2) the national bank has, for the protection of the bank, reasonable policies and procedures to preserve the separate corporate identity and limited liability of the national bank and the financial subsidiaries of the national bank; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/24a?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§24a. Financial subsidiaries of national banks","tname":"Banks and Banking","by":{"0":"20, 3, 8, 11, 20, 28"}},{"t":"usc","label":"12 U.S.C. § 26","url":"https://www.law.cornell.edu/uscode/text/12/26","by":{"0":"13"}},{"t":"usc","label":"12 U.S.C. § 43","url":"https://www.law.cornell.edu/uscode/text/12/43","subs":["(a)","(b)(1)"],"stext":{"head":"§43. Interpretations concerning preemption of certain State laws","paras":[[0,"(a) Notice and opportunity for comment required"],[0,"Before issuing any opinion letter or interpretive rule, in response to a request or upon the agency's own motion, that concludes that Federal law preempts the application to a national bank of any State law regarding community reinvestment, consumer protection, fair lending, or the establishment of intrastate branches, or before making a determination under section 36(f)(1)(A)(ii) of this title, the appropriate Federal banking agency (as defined in section 1813 of this title) shall—"],[1,"(1) publish in the Federal Register notice of the preemption or discrimination issue that the agency is considering (including a description of each State law at issue);"],[1,"(2) give interested parties not less than 30 days in which to submit written comments; and"],[1,"(3) in developing the final opinion letter or interpretive rule issued by the agency, or making any determination under section 36(f)(1)(A)(ii) of this title, consider any comments received."],[0,"(b) Publication required"],[0,"The appropriate Federal banking agency shall publish in the Federal Register—"],[1,"(1) any final opinion letter or interpretive rule concluding that Federal law preempts the application of any State law regarding community reinvestment, consumer protection, fair lending, or establishment of intrastate branches to a national bank; and"],[1,"(2) any determination under section 36(f)(1)(A)(ii) of this title."],[0,"(c) Exceptions"],[0,"(1) No new issue or significant basis"],[1,"This section shall not apply with respect to any opinion letter or interpretive rule that—"],[2,"(A) raises issues of Federal preemption of State law that are essentially identical to those previously resolved by the courts or on which the agency has previously issued an opinion letter or interpretive rule; or"],[2,"(B) responds to a request that contains no significant legal basis on which to make a preemption determination."],[0,"(2) Judicial, legislative, or intragovernmental materials"],[1,"This section shall not apply with respect to materials prepared for use in judicial proceedings or submission to Congress or a Member of Congress, or for intragovernmental use."],[0,"(3) Emergency"],[1,"The appropriate Federal banking agency may make exceptions to subsection (a) if—"],[2,"(A) the agency determines in writing that the exception is necessary to avoid a serious and imminent threat to the safety and soundness of any national bank; or"],[2,"(B) the opinion letter or interpretive rule is issued in connection with—"],[3,"(i) an acquisition of 1 or more banks in default or in danger of default (as such terms are defined in section 1813 of this title); or"],[3,"(ii) an acquisition with respect to which the Federal Deposit Insurance Corporation provides assistance under section 1823(c) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/43?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§43. Interpretations concerning preemption of certain State laws","tname":"Banks and Banking","by":{"0":"7, 15, 16, 15, 15"}},{"t":"usc","label":"12 U.S.C. § 92","url":"https://www.law.cornell.edu/uscode/text/12/92","by":{"0":"27"}},{"t":"usc","label":"12 U.S.C. § 93a","url":"https://www.law.cornell.edu/uscode/text/12/93a","stext":{"head":"§93a. Authority to prescribe rules and regulations","paras":[[0,"Except to the extent that authority to issue such rules and regulations has been expressly and exclusively granted to another regulatory agency, the Comptroller of the Currency is authorized to prescribe rules and regulations to carry out the responsibilities of the office, except that the authority conferred by this section does not apply to section 36 of this title or to securities activities of National Banks under the Act commonly known as the \"Glass-Steagall Act\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/93a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§93a. Authority to prescribe rules and regulations","tname":"Banks and Banking","by":{"0":"13, 14, 15"}},{"t":"usc","label":"12 U.S.C. § 221a","url":"https://www.law.cornell.edu/uscode/text/12/221a","subs":["(b)"],"stext":{"head":"§221a. Additional definitions","paras":[[0,"As used in this chapter—"],[0,"(a) The terms \"banks\", \"national bank\", \"national banking association\", \"member bank\", \"board\", \"district\", and \"reserve bank\" shall have the meanings assigned to them in section 221 of this title."],[0,"(b) Except where otherwise specifically provided, the term \"affiliate\" shall include any corporation, business trust, association, or other similar organization—"],[1,"(1) Of which a member bank, directly or indirectly, owns or controls either a majority of the voting shares or more than 50 per centum of the number of shares voted for the election of its directors, trustees, or other persons exercising similar functions at the preceding election, or controls in any manner the election of a majority of its directors, trustees, or other persons exercising similar functions; or"],[1,"(2) Of which control is held, directly or indirectly, through stock ownership or in any other manner, by the shareholders of a member bank who own or control either a majority of the shares of such bank or more than 50 per centum of the number of shares voted for the election of directors of such bank at the preceding election, or by trustees for the benefit of the shareholders of any such bank; or"],[1,"(3) Of which a majority of its directors, trustees, or other persons exercising similar functions are directors of any one member bank; or"],[1,"(4) Which owns or controls, directly or indirectly, either a majority of the shares of capital stock of a member bank or more than 50 per centum of the number of shares voted for the election of directors of a member bank at the preceding election, or controls in any manner the election of a majority of the directors of a member bank, or for the benefit of whose shareholders or members all or substantially all the capital stock of a member bank is held by trustees."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/221a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§221a. Additional definitions","tname":"Banks and Banking","by":{"0":"18"}},{"t":"usc","label":"12 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/12/371","subs":["(a)"],"stext":{"head":"§371. Real estate loans","paras":[[0,"(a) Authorization to make real estate loans; orders, rules, and regulations of Comptroller of the Currency"],[0,"Any national banking association may make, arrange, purchase or sell loans or extensions of credit secured by liens on interests in real estate, subject to section 1828(o) of this title and such restrictions and requirements as the Comptroller of the Currency may prescribe by regulation or order."],[0,"(b) Eligibility for discount as commercial paper of notes representing loans financing construction of residential or farm buildings; prerequisites"],[0,"Notes representing loans made under this section to finance the construction of residential or farm buildings and having maturities not to exceed nine months shall be eligible for discount as commercial paper within the terms of the first paragraph of section 343 of this title if accompanied by a valid and binding agreement to advance the full amount of the loan upon the completion of the building entered into by an individual, partnership, association, or corporation acceptable to the discounting bank."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/371?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§371. Real estate loans","tname":"Banks and Banking","by":{"0":"3, 8, 14, 17"}},{"t":"usc","label":"12 U.S.C. § 481","url":"https://www.law.cornell.edu/uscode/text/12/481","stext":{"head":"§481. Appointment of examiners; examination of member banks, State banks, and trust companies; reports","paras":[[0,"The Comptroller of the Currency, with the approval of the Secretary of the Treasury, shall appoint examiners who shall examine every national bank as often as the Comptroller of the Currency shall deem necessary. The examiner making the examination of any national bank shall have power to make a thorough examination of all the affairs of the bank and in doing so he shall have power to administer oaths and to examine any of the officers and agents thereof under oath and shall make a full and detailed report of the condition of said bank to the Comptroller of the Currency: Provided, That in making the examination of any national bank the examiners shall include such an examination of the affairs of all its affiliates other than member banks as shall be necessary to disclose fully the relations between such bank and such affiliates and the effect of such relations upon the affairs of such bank; and in the event of the refusal to give any information required in the course of the examination of any such affiliate, or in the event of the refusal to permit such examination, all the rights, privileges, and franchises of the bank shall be subject to forfeiture in accordance with section 2 of the Federal Reserve Act, as amended (U.S.C., title 12, secs. 141, 222–225, 281–286, and 502).1 The Comptroller of the Currency shall have power, and he is authorized, to publish the report of his examination of any national banking association or affiliate which shall not within one hundred and twenty days after notification of the recommendations or suggestions of the Comptroller, based on said examination, have complied with the same to his satisfaction. Ninety days' notice prior to such publicity shall be given to the bank or affiliate."],[0,"The examiner making the examination of any affiliate of a national bank shall have power to make a thorough examination of all the affairs of the affiliate, and in doing so he shall have power to administer oaths and to examine any of the officers, directors, employees, and agents thereof under oath and to make a report of his findings to the Comptroller of the Currency. If any affiliate of a national bank refuses to pay any assessments, fees, or other charges imposed by the Comptroller of the Currency pursuant to this subchapter or fails to make such payment not later than 60 days after the date on which they are imposed, the Comptroller of the Currency may impose such assessments, fees, or charges against the affiliated national bank, and such assessments, fees, or charges shall be paid by such national bank. If the affiliation is with 2 or more national banks, such assessments, fees, or charges may be imposed on, and collected from, any or all of such national banks in such proportions as the Comptroller of the Currency may prescribe. The examiners and assistant examiners making the examinations of national banking associations and affiliates thereof herein provided for and the chief examiners, reviewing examiners and other persons whose services may be required in connection with such examinations or the reports thereof, shall be employed by the Comptroller of the Currency with the approval of the Secretary of the Treasury; the employment and compensation of examiners, chief examiners, reviewing examiners, assistant examiners, and of the other employees of the office of the Comptroller of the Currency whose compensation is and shall be paid from assessments on banks or affiliates thereof or from other fees or charges imposed pursuant to this subchapter shall be set and adjusted subject to chapter 71 of title 5 and without regard to the provisions of other laws applicable to officers or employees of the United States. The funds derived from such assessments, fees, or charges may be deposited by the Comptroller of the Currency in accordance with the provisions of section 192 of this title and shall not be construed to be Government funds or appropriated monies; and the Comptroller of the Currency is authorized and empowered to prescribe regulations governing the computation and assessment of the expenses of examinations herein provided for and the collection of such assessments from the banks and/or affiliates examined or of other fees or charges imposed pursuant to this subchapter. Such funds shall not be subject to apportionment for the purpose of chapter 15 of title 31 or under any other authority. If any affiliate of a national bank shall refuse to permit an examiner to make an examination of the affiliate or shall refuse to give any information required in the course of any such examination, the national bank with which it is affiliated shall be subject to a penalty of not more than $5,000 for each day that any such refusal shall continue. Such penalty may be assessed by the Comptroller of the Currency and collected in the same manner as expenses of examinations. The Comptroller of the Currency, upon the request of the Board of Governors of the Federal Reserve System, is authorized to assign examiners appointed under this subchapter to examine foreign operations of State banks which are members of the Federal Reserve System."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/481?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§481. Appointment of examiners; examination of member banks, State banks, and trust companies; reports","tname":"Banks and Banking","by":{"0":"18"}},{"t":"usc","label":"12 U.S.C. § 484","url":"https://www.law.cornell.edu/uscode/text/12/484","subs":["(a)"],"stext":{"head":"§484. Limitation on visitorial powers","paras":[[0,"(a) No national bank shall be subject to any visitorial powers except as authorized by Federal law, vested in the courts of justice or such as shall be, or have been exercised or directed by Congress or by either House thereof or by any committee of Congress or of either House duly authorized."],[0,"(b) Notwithstanding subsection (a), lawfully authorized State auditors and examiners may, at reasonable times and upon reasonable notice to a bank, review its records solely to ensure compliance with applicable State unclaimed property or escheat laws upon reasonable cause to believe that the bank has failed to comply with such laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/484?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":2,"head":"§484. Limitation on visitorial powers","tname":"Banks and Banking","by":{"0":"4, 5, 7, 16, 17, 18"}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","subs":["(b)"],"by":{"0":"13"}},{"t":"usc","label":"15 U.S.C. § 6701","url":"https://www.law.cornell.edu/uscode/text/15/6701","subs":["(d)(2)(c)(i)"],"stext":{"head":"§6701. Operation of State law","paras":[[0,"(a) State regulation of the business of insurance"],[0,"The Act entitled \"An Act to express the intent of Congress with reference to the regulation of the business of insurance\" and approved March 9, 1945 (15 U.S.C. 1011 et seq.) (commonly referred to as the \"McCarran-Ferguson Act\") remains the law of the United States."],[0,"(b) Mandatory insurance licensing requirements"],[0,"No person shall engage in the business of insurance in a State as principal or agent unless such person is licensed as required by the appropriate insurance regulator of such State in accordance with the relevant State insurance law, subject to subsections (c), (d), and (e)."],[0,"(c) Affiliations"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), no State may, by statute, regulation, order, interpretation, or other action, prevent or restrict a depository institution, or an affiliate thereof, from being affiliated directly or indirectly or associated with any person, as authorized or permitted by this Act or any other provision of Federal law."],[0,"(2) Insurance"],[1,"With respect to affiliations between depository institutions, or any affiliate thereof, and any insurer, paragraph (1) does not prohibit—"],[2,"(A) any State from—"],[3,"(i) collecting, reviewing, and taking actions (including approval and disapproval) on applications and other documents or reports concerning any proposed acquisition of, or a change or continuation of control of, an insurer domiciled in that State; and"],[3,"(ii) exercising authority granted under applicable State law to collect information concerning any proposed acquisition of, or a change or continuation of control of, an insurer engaged in the business of insurance in, and regulated as an insurer by, such State;"],[2,"during the 60-day period preceding the effective date of the acquisition or change or continuation of control, so long as the collecting, reviewing, taking actions, or exercising authority by the State does not have the effect of discriminating, intentionally or unintentionally, against a depository institution or an affiliate thereof, or against any other person based upon an association of such person with a depository institution;"],[2,"(B) any State from requiring any person that is acquiring control of an insurer domiciled in that State to maintain or restore the capital requirements of that insurer to the level required under the capital regulations of general applicability in that State to avoid the requirement of preparing and filing with the insurance regulatory authority of that State a plan to increase the capital of the insurer, except that any determination by the State insurance regulatory authority with respect to such requirement shall be made not later than 60 days after the date of notification under subparagraph (A); or"],[2,"(C) any State from restricting a change in the ownership of stock in an insurer, or a company formed for the purpose of controlling such insurer, after the conversion of the insurer from mutual to stock form so long as such restriction does not have the effect of discriminating, intentionally or unintentionally, against a depository institution or an affiliate thereof, or against any other person based upon an association of such person with a depository institution."],[0,"(d) Activities"],[0,"(1) In general"],[1,"Except as provided in paragraph (3), and except with respect to insurance sales, solicitation, and cross marketing activities, which shall be governed by paragraph (2), no State may, by statute, regulation, order, interpretation, or other action, prevent or restrict a depository institution or an affiliate thereof from engaging directly or indirectly, either by itself or in conjunction with an affiliate, or any other person, in any activity authorized or permitted under this Act and the amendments made by this Act."],[0,"(2) Insurance sales"],[0,"(A) In general"],[2,"In accordance with the legal standards for preemption set forth in the decision of the Supreme Court of the United States in Barnett Bank of Marion County N.A. v. Nelson, 517 U.S. 25 (1996), no State may, by statute, regulation, order, interpretation, or other action, prevent or significantly interfere with the ability of a depository institution, or an affiliate thereof, to engage, directly or indirectly, either by itself or in conjunction with an affiliate or any other person, in any insurance sales, solicitation, or crossmarketing activity."],[0,"(B) Certain State laws preserved"],[2,"Notwithstanding subparagraph (A), a State may impose any of the following restrictions, or restrictions that are substantially the same as but no more burdensome or restrictive than those in each of the following clauses:"],[3,"(i) Restrictions prohibiting the rejection of an insurance policy by a depository institution or an affiliate of a depository institution, solely because the policy has been issued or underwritten by any person who is not associated with such depository institution or affiliate when the insurance is required in connection with a loan or extension of credit."],[3,"(ii) Restrictions prohibiting a requirement for any debtor, insurer, or insurance agent or broker to pay a separate charge in connection with the handling of insurance that is required in connection with a loan or other extension of credit or the provision of another traditional banking product by a depository institution, or any affiliate of a depository institution, unless such charge would be required when the depository institution or affiliate is the licensed insurance agent or broker providing the insurance."],[3,"(iii) Restrictions prohibiting the use of any advertisement or other insurance promotional material by a depository institution or any affiliate of a depository institution that would cause a reasonable person to believe mistakenly that—"],[4,"(I) the Federal Government or a State is responsible for the insurance sales activities of, or stands behind the credit of, the institution or affiliate; or"],[4,"(II) a State, or the Federal Government guarantees any returns on insurance products, or is a source of payment on any insurance obligation of or sold by the institution or affiliate;"],[3,"(iv) Restrictions prohibiting the payment or receipt of any commission or brokerage fee or other valuable consideration for services as an insurance agent or broker to or by any person, unless such person holds a valid State license regarding the applicable class of insurance at the time at which the services are performed, except that, in this clause, the term \"services as an insurance agent or broker\" does not include a referral by an unlicensed person of a customer or potential customer to a licensed insurance agent or broker that does not include a discussion of specific insurance policy terms and conditions."],[3,"(v) Restrictions prohibiting any compensation paid to or received by any individual who is not licensed to sell insurance, for the referral of a customer that seeks to purchase, or seeks an opinion or advice on, any insurance product to a person that sells or provides opinions or advice on such product, based on the purchase of insurance by the customer."],[3,"(vi) Restrictions prohibiting the release of the insurance information of a customer (defined as information concerning the premiums, terms, and conditions of insurance coverage, including expiration dates and rates, and insurance claims of a customer contained in the records of the depository institution or an affiliate thereof) to any person other than an officer, director, employee, agent, or affiliate of a depository institution, for the purpose of soliciting or selling insurance, without the express consent of the customer, other than a provision that prohibits—"],[4,"(I) a transfer of insurance information to an unaffiliated insurer in connection with transferring insurance in force on existing insureds of the depository institution or an affiliate thereof, or in connection with a merger with or acquisition of an unaffiliated insurer; or"],[4,"(II) the release of information as otherwise authorized by State or Federal law."],[3,"(vii) Restrictions prohibiting the use of health information obtained from the insurance records of a customer for any purpose, other than for its activities as a licensed agent or broker, without the express consent of the customer."],[3,"(viii) Restrictions prohibiting the extension of credit or any product or service that is equivalent to an extension of credit, lease or sale of property of any kind, or furnishing of any services or fixing or varying the consideration for any of the foregoing, on the condition or requirement that the customer obtain insurance from a depository institution or an affiliate of a depository institution, or a particular insurer, agent, or broker, other than a prohibition that would prevent any such depository institution or affiliate—"],[4,"(I) from engaging in any activity described in this clause that would not violate section 106 of the Bank Holding Company Act Amendments of 1970 [12 U.S.C. 1971 et seq.], as interpreted by the Board of Governors of the Federal Reserve System; or"],[4,"(II) from informing a customer or prospective customer that insurance is required in order to obtain a loan or credit, that loan or credit approval is contingent upon the procurement by the customer of acceptable insurance, or that insurance is available from the depository institution or an affiliate of the depository institution."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/6701?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§6701. Operation of State law","tname":"Commerce and Trade","by":{"0":"16"}},{"t":"usc","label":"15 U.S.C. § 6714","url":"https://www.law.cornell.edu/uscode/text/15/6714","subs":["(a)","(e)"],"by":{"0":"16, 16, 16"}},{"t":"reg","label":"3 C.F.R. pt. 206","url":"https://www.ecfr.gov/current/title-3/part-206","by":{"0":"12"}},{"t":"reg","label":"61 Fed. Reg. 60,354","url":"https://www.govinfo.gov/link/fr/61/60354","by":{"0":"19"}},{"t":"reg","label":"65 Fed. Reg. 12,911","url":"https://www.govinfo.gov/link/fr/65/12911","by":{"0":"14"}}]};